        ELSIF Logical_Operator1_out1 = '1' THEN 
          HDL_Counter_out1 <= HDL_Counter_out1 + to_unsigned(1, 33);
        END IF;
      END IF;
    END IF;
  END PROCESS HDL_Counter_process;


